int set_ext_registers(struct task_struct *child, void __user *uregs) {
    int ret = 0;
    struct user_ext_regs *kregs = NULL;

    /* Allocate memory for kernel copy of extended registers */
    kregs = kmalloc(sizeof(struct user_ext_regs), GFP_KERNEL);
    if (!kregs) {
        return -ENOMEM;
    }

    /* Copy extended registers from user space to kernel space */
    if (copy_from_user(kregs, uregs, sizeof(struct user_ext_regs))) {
        ret = -EFAULT;
        goto out;
    }

    /* Flush and release coprocessors if applicable */
    flush_and_release_coprocessors();

    /* Copy extended register values to the task's thread information and register structure */
    if (copy_to_user(&child->thread.ext_regs, kregs, sizeof(struct user_ext_regs))) {
        ret = -EFAULT;
        goto out;
    }

out:
    kfree(kregs);
    return ret;
}
